14	export async function createCodeAssistContentGenerator(
15	  httpOptions: HttpOptions,
16	  authType: AuthType,
17	  config: Config,
18	  sessionId?: string,
19	): Promise<ContentGenerator> {
20	  if (
21	    authType === AuthType.LOGIN_WITH_GOOGLE ||
22	    authType === AuthType.COMPUTE_ADC
23	  ) {
24	    const authClient = await getOauthClient(authType, config);
25	    const userData = await setupUser(
26	      authClient,
27	      config.getValidationHandler(),
28	      httpOptions,
29	    );
30	    return new CodeAssistServer(
31	      authClient,
32	      userData.projectId,
33	      httpOptions,
34	      sessionId,
35	      userData.userTier,
36	      userData.userTierName,
37	      userData.paidTier,
38	      config,
39	    );
40	  }
41	
42	  throw new Error(`Unsupported authType: ${authType}`);
43	}
