45	export function getCodeAssistServer(
46	  config: Config,
47	): CodeAssistServer | undefined {
48	  let server = config.getContentGenerator();
49	
50	  // Unwrap LoggingContentGenerator if present
51	  if (server instanceof LoggingContentGenerator) {
52	    server = server.getWrapped();
53	  }
54	
55	  if (!(server instanceof CodeAssistServer)) {
56	    return undefined;
57	  }
58	  return server;
59	}
